head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

    scwin.setData = function() {
        var json = [
            { "col1" : "1", "col2" : "1", "col3" : "a", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "1", "col3" : "a", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "2", "col3" : "a", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "2", "col3" : "b", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "2", "col3" : "b", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "3", "col3" : "c", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "3", "col3" : "c", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "3", "col3" : "c", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "4", "col3" : "c", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "4", "col3" : "d", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "4", "col3" : "d", "col4" : "1", "col5" : "1"},
            { "col1" : "1", "col2" : "4", "col3" : "d", "col4" : "1", "col5" : "1"}
        ]
        dataList1.setJSON(json)
    };

    scwin.trigger1_onclick = function() {
        scwin.setData();
    };

    scwin.trigger2_onclick = function() {
	console.log('---------------1')
        gridView1.mergeCells("bycol");
    };

    scwin.trigger3_onclick = function() {
	console.log('---------------2')
        gridView1.mergeCells("bycolupper");
    };

    scwin.trigger4_onclick = function() {
	console.log('---------------3')
        gridView1.mergeClear();
    };

    scwin.trigger22_onclick = function() {
        gridView2.mergeCells("bycol");
    };

    scwin.trigger33_onclick = function() {
        gridView2.mergeCells("bycolupper", {
            "upperColumn" : {
                col5: "col2,col3"
            }
        });
    };

    scwin.trigger44_onclick = function() {
        gridView2.mergeClear();
    };


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_1').getAttribute('rowspan') == 2;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_2').getAttribute('rowspan') == 3;
	}
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_3').getAttribute('rowspan') == 12;
	}
	scwin.checkVal4 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_4').getAttribute('rowspan') == 2;
	}
	scwin.checkVal5 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_2_1').getAttribute('rowspan') == 3;
	}	
	scwin.checkVal6 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_5_4').getAttribute('rowspan') == 3;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
